package com.dialogueguard;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(DialogueGuardPlugin.CONFIG_GROUP)
public interface DialogueGuardConfig extends Config
{
	@ConfigItem(keyName = "guardDigits", name = "Guard number keys", position = 0,
		description = "Block 1-9 (dialogue option keys, top row or numpad) when they spill past the end of a dialogue.")
	default boolean guardDigits()
	{
		return true;
	}

	@ConfigItem(keyName = "guardSpace", name = "Guard space", position = 1,
		description = "Block the space bar (click-to-continue) when it spills past the end of a dialogue.")
	default boolean guardSpace()
	{
		return true;
	}

	@ConfigItem(keyName = "guardEnter", name = "Guard enter", position = 2,
		description = "Block enter when it spills past the end of a dialogue. This also stops a stray enter from sending whatever was already in the chat box.")
	default boolean guardEnter()
	{
		return true;
	}

	@Range(min = 100, max = 3000)
	@ConfigItem(keyName = "windowMs", name = "Guard window (ms)", position = 3,
		description = "After the key that ends a dialogue, further guarded keys are blocked until you stop pressing them for this long. Pressing any other key (a letter) ends the guard at once.")
	default int windowMs()
	{
		return 600;
	}

	@ConfigItem(keyName = "noLeadingSpace", name = "Never start a message with a space", position = 4,
		description = "Block the space bar whenever the chat box is empty and no dialogue is open, so a message can never begin with spaces. Space still works in dialogues and once you've typed something.")
	default boolean noLeadingSpace()
	{
		return true;
	}

	@ConfigItem(keyName = "clearJunkOnDialogue", name = "Clear leftover junk when a dialogue opens", position = 5,
		description = "If the chat box holds only digits and spaces (a '111' left over from the last conversation) when a dialogue opens, clear it so it can't be sent later by accident. Real text is never touched.")
	default boolean clearJunkOnDialogue()
	{
		return true;
	}

	@ConfigItem(keyName = "showHint", name = "Show hint", position = 6,
		description = "Briefly show how many keys were blocked above the chat box, so a blocked key never looks like a dead keyboard.")
	default boolean showHint()
	{
		return false;
	}

	@ConfigItem(keyName = "showLifetime", name = "Show keys blocked all-time in hint", position = 7,
		description = "Append the running total of keys this plugin has blocked for you to the hint.")
	default boolean showLifetime()
	{
		return true;
	}
}

/*
 * Dialogue Guard: the small "blocked N" note above the chat box, so a blocked key does not look like a dead keyboard.
 * BSD-2-Clause, see LICENSE.
 */
package com.dialogueguard;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class DialogueGuardHint extends Overlay
{
	private static final long SHOW_MS = 1500;
	private static final Color BG = new Color(0, 0, 0, 160);
	private static final Color FG = new Color(255, 200, 80);
	private static final int PAD_X = 5;
	private static final int PAD_Y = 2;
	/** gap between the hint and the chat box's right edge */
	private static final int INSET_X = 4;
	/** gap above the chat box; smaller than INSET_X so the two gaps look the same against the chat box's frame */
	private static final int INSET_Y = 2;
	/** what the hint sits above: the message area, or the tab row when chat is collapsed in resizable mode */
	private static final int[] ANCHORS = {InterfaceID.Chatbox.CHATAREA, InterfaceID.Chatbox.CONTROLS};

	private final Client client;
	private final DialogueGuardConfig config;
	private final Font font = FontManager.getRunescapeSmallFont();

	/** keys blocked in the current burst (a burst ends once the hint has faded) */
	private int burst;
	private volatile long showUntil;
	/** the line to draw, built when a key is blocked rather than every frame */
	private volatile String text = "";

	@Inject
	public DialogueGuardHint(Client client, DialogueGuardConfig config)
	{
		this.client = client;
		this.config = config;
		// Placed by hand against the chat box rather than with ABOVE_CHATBOX_RIGHT: in fixed mode RuneLite moves that
		// corner to the bottom right of the game view and clips it there, and a snap corner lays out each frame with
		// the previous frame's width, so the first frame of a hint would hang off the right edge.
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** Called from the key thread for every blocked key that should be shown. */
	void flash(int allTime)
	{
		long now = System.currentTimeMillis();
		if (now > showUntil)
		{
			burst = 0;
		}
		burst++;
		StringBuilder sb = new StringBuilder("Dialogue Guard: blocked ").append(burst).append(burst == 1 ? " key" : " keys");
		if (config.showLifetime())
		{
			sb.append(" (").append(String.format("%,d", allTime)).append(" all-time)");
		}
		text = sb.toString();
		showUntil = now + SHOW_MS;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showHint() || System.currentTimeMillis() > showUntil)
		{
			return null;
		}
		Rectangle chat = chatBounds();
		if (chat == null)
		{
			return null;
		}
		String line = text;
		g.setFont(font);
		FontMetrics fm = g.getFontMetrics();
		int w = fm.stringWidth(line) + 2 * PAD_X;
		int h = fm.getHeight() + 2 * PAD_Y;
		// right-aligned to the chat box, just above it; kept on the canvas if the chat box is narrower than the line
		int x = Math.max(0, Math.min(chat.x + chat.width - INSET_X - w, client.getCanvasWidth() - w));
		int y = Math.max(0, chat.y - INSET_Y - h);
		g.setColor(BG);
		g.fillRoundRect(x, y, w, h, 6, 6);
		g.setColor(FG);
		g.drawString(line, x + PAD_X, y + fm.getAscent() + PAD_Y);
		// drawn at absolute coordinates, so nothing for the renderer to lay out
		return null;
	}

	private Rectangle chatBounds()
	{
		for (int id : ANCHORS)
		{
			Widget w = client.getWidget(id);
			if (w != null && !w.isHidden())
			{
				Rectangle b = w.getBounds();
				if (b != null && b.width > 0)
				{
					return b;
				}
			}
		}
		return null;
	}
}

/*
 * Dialogue Guard: stops dialogue-skipping keys from spilling into the chat box.
 * BSD-2-Clause, see LICENSE.
 *
 * This class is the RuneLite wiring: it feeds dialogue open/close events and key events into GuardState (the
 * decision logic) and acts on its answer. Two extras live here because they need the client: the leading-space
 * rule (space is dropped while the chat box is empty) and clearing digit-only leftovers when a dialogue opens.
 *
 * Only presses (and the keyTyped that follows) are ever consumed. Releases always go through: a stray release is
 * harmless, while a swallowed one could leave the client or another plugin thinking a key is still held.
 */
package com.dialogueguard;

import com.google.inject.Provides;
import java.awt.event.KeyEvent;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Dialogue Guard",
	description = "Stops dialogue-skipping keys (1-9, space, enter) from spilling into the chat box when a dialogue ends while you're still pressing them",
	tags = {"dialogue", "chat", "keyboard", "spam", "qol"}
)
public class DialogueGuardPlugin extends Plugin implements KeyListener
{
	static final String CONFIG_GROUP = "dialogueguard";
	/** config key the all-time counter is persisted under (not shown in the settings panel) */
	private static final String KEY_BLOCKED = "keysBlocked";
	/** the all-time counter is written at most this often while keys are being blocked (and always on shutdown) */
	private static final long PERSIST_INTERVAL_MS = 1000;
	/** chat-box contents that are safe to clear: digits and spaces only */
	private static final Pattern JUNK = Pattern.compile("[0-9 ]+");

	@Inject private Client client;
	@Inject private ConfigManager configManager;
	@Inject private KeyManager keyManager;
	@Inject private OverlayManager overlayManager;
	@Inject private DialogueGuardConfig config;
	@Inject private DialogueGuardHint hint;

	private final GuardState state = new GuardState(() -> config.windowMs());
	/** keys blocked since the plugin was installed; persisted in the config */
	private final AtomicInteger counter = new AtomicInteger();

	/** the decision made in keyPressed, so the keyTyped for the same key follows it */
	private volatile boolean blockingCurrentKey;
	private volatile long lastPersist;

	@Provides
	DialogueGuardConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DialogueGuardConfig.class);
	}

	@Override
	protected void startUp()
	{
		state.reset();
		blockingCurrentKey = false;
		counter.set(loadBlocked());
		keyManager.registerKeyListener(this);
		overlayManager.add(hint);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(this);
		overlayManager.remove(hint);
		persistBlocked();
		state.reset();
	}

	// ------------------------------------------------------------------ all-time counter

	private int loadBlocked()
	{
		try
		{
			String v = configManager.getConfiguration(CONFIG_GROUP, KEY_BLOCKED);
			return v == null ? 0 : Integer.parseInt(v);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private void persistBlocked()
	{
		configManager.setConfiguration(CONFIG_GROUP, KEY_BLOCKED, String.valueOf(counter.get()));
	}

	/** One more key kept out of the chat box. The hint only flashes for dialogue spill-over; a dropped leading space is silent. */
	private void recordBlock(long now, boolean flash)
	{
		counter.incrementAndGet();
		if (now - lastPersist > PERSIST_INTERVAL_MS)
		{
			lastPersist = now;
			persistBlocked();
		}
		if (flash && config.showHint())
		{
			hint.flash(counter.get());
		}
	}

	// ------------------------------------------------------------------ dialogue state (client thread)

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		// Only where interfaces really go away without close events. A region load (LOADING) keeps an open dialogue
		// open, and forgetting it would let the leading-space rule eat the space that continues it.
		if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING)
		{
			state.reset();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e)
	{
		if (DialogueKeys.isDialogue(e.getGroupId()))
		{
			state.dialogueOpened(e.getGroupId());
			if (config.clearJunkOnDialogue())
			{
				clearJunkFromChat();
			}
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed e)
	{
		if (DialogueKeys.isDialogue(e.getGroupId()))
		{
			state.dialogueClosed(e.getGroupId());
		}
	}

	/** Wipe the chat box if all it holds is digits and spaces left over from an earlier dialogue. Client thread. */
	private void clearJunkFromChat()
	{
		String typed = client.getVarcStrValue(VarClientID.CHATINPUT);
		if (typed == null || typed.isEmpty() || !JUNK.matcher(typed).matches())
		{
			return;
		}
		client.setVarcStrValue(VarClientID.CHATINPUT, "");
		client.runScript(ScriptID.CHAT_PROMPT_INIT);   // redraw the input line
	}

	// ------------------------------------------------------------------ keys (AWT thread)

	private boolean isGuarded(int keyCode)
	{
		switch (DialogueKeys.kind(keyCode))
		{
			case DIGIT:
				return config.guardDigits();
			case SPACE:
				return config.guardSpace();
			case ENTER:
				return config.guardEnter();
			default:
				return false;
		}
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		blockingCurrentKey = false;
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		int code = e.getKeyCode();
		if (!isGuarded(code))
		{
			if (!DialogueKeys.isModifier(code))
			{
				state.otherKeyPressed();
			}
			return;
		}
		long now = System.currentTimeMillis();
		switch (state.guardedKeyPressed(now, DialogueKeys.pageAccepts(state.page(), code)))
		{
			case HOLD:
				// the open page already has its key: blocked, but not counted or shown
				blockingCurrentKey = true;
				e.consume();
				return;
			case BLOCK:
				block(e, now, true);
				return;
			case PASS:
				break;
		}
		// Not spill-over. One more rule for space: a message never starts with one.
		if (DialogueKeys.kind(code) == DialogueKeys.Kind.SPACE && config.noLeadingSpace() && !state.dialogueOpen() && chatInputIsBlank())
		{
			state.touch(now);
			block(e, now, false);
		}
	}

	private void block(KeyEvent e, long now, boolean flash)
	{
		blockingCurrentKey = true;
		recordBlock(now, flash);
		e.consume();
	}

	/**
	 * True when the chat line has nothing typed in it yet (or only spaces) and is where keys are going. A chat-box
	 * prompt (bank or GE search, "Enter amount", a name) keeps its text elsewhere and leaves the chat line empty,
	 * so the rule must stand aside while one is open or it would eat the space in "dragon bones".
	 */
	private boolean chatInputIsBlank()
	{
		if (client.getVarcIntValue(VarClientID.MESLAYERMODE) != 0)
		{
			return false;
		}
		String typed = client.getVarcStrValue(VarClientID.CHATINPUT);
		return typed == null || typed.trim().isEmpty();
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
		if (blockingCurrentKey)
		{
			e.consume();
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		if (isGuarded(e.getKeyCode()))
		{
			state.guardedKeyReleased(System.currentTimeMillis());
		}
	}
}

/*
 * Dialogue Guard: which interfaces are dialogues, which keys are dialogue keys, and which keys each dialogue acts on.
 * BSD-2-Clause, see LICENSE.
 */
package com.dialogueguard;

import java.awt.event.KeyEvent;
import net.runelite.api.gameval.InterfaceID;

/** Plain lookups with no client state, kept apart from the plugin so they can be tested on their own. */
final class DialogueKeys
{
	/** The kinds of key the guard cares about. */
	enum Kind
	{
		/** 1-9 on the top row or the numpad: picks an option, and types a digit into chat */
		DIGIT,
		/** continues a page, and types a space into chat */
		SPACE,
		/** advances nothing, but sends whatever is in the chat box */
		ENTER,
		/** anything else */
		OTHER
	}

	/** Interface groups that take a key to advance: NPC/player chat, option menus, message/sprite boxes, level-ups, make-x. */
	private static final int[] DIALOGUE_GROUPS = {
		InterfaceID.CHAT_LEFT, InterfaceID.CHAT_RIGHT, InterfaceID.CHATMENU, InterfaceID.MESSAGEBOX,
		InterfaceID.OBJECTBOX, InterfaceID.OBJECTBOX_DOUBLE, InterfaceID.LEVELUP_DISPLAY, InterfaceID.SKILLMULTI,
	};

	private DialogueKeys()
	{
	}

	static boolean isDialogue(int groupId)
	{
		for (int g : DIALOGUE_GROUPS)
		{
			if (g == groupId)
			{
				return true;
			}
		}
		return false;
	}

	static Kind kind(int keyCode)
	{
		if ((keyCode >= KeyEvent.VK_1 && keyCode <= KeyEvent.VK_9)
			|| (keyCode >= KeyEvent.VK_NUMPAD1 && keyCode <= KeyEvent.VK_NUMPAD9))
		{
			return Kind.DIGIT;
		}
		switch (keyCode)
		{
			case KeyEvent.VK_SPACE:
				return Kind.SPACE;
			case KeyEvent.VK_ENTER:
				return Kind.ENTER;
			default:
				return Kind.OTHER;
		}
	}

	/** Modifier presses (and keys Java can't name) say nothing about whether the player is typing. */
	static boolean isModifier(int keyCode)
	{
		return keyCode == KeyEvent.VK_SHIFT || keyCode == KeyEvent.VK_CONTROL || keyCode == KeyEvent.VK_ALT
			|| keyCode == KeyEvent.VK_META || keyCode == KeyEvent.VK_CAPS_LOCK || keyCode == KeyEvent.VK_UNDEFINED;
	}

	/**
	 * Whether a page acts on this key: option menus take digits, make-x takes digits and space (make the selected
	 * amount), everything else is click-to-continue and takes space. Enter advances nothing.
	 */
	static boolean pageAccepts(int groupId, int keyCode)
	{
		Kind kind = kind(keyCode);
		switch (groupId)
		{
			case InterfaceID.CHATMENU:
				return kind == Kind.DIGIT;
			case InterfaceID.SKILLMULTI:
				return kind == Kind.DIGIT || kind == Kind.SPACE;
			default:
				return kind == Kind.SPACE;
		}
	}
}

/*
 * Dialogue Guard: the decision logic, kept free of RuneLite so it can be read and tested on its own.
 * BSD-2-Clause, see LICENSE.
 */
package com.dialogueguard;

import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.LongSupplier;

/**
 * Decides whether a dialogue key (1-9, space, enter) should reach the game.
 *
 * <p>A dialogue page is <em>taken</em> by the first key it accepts (space continues a chat page, a digit picks
 * an option). A key the page ignores, such as a space mashed onto an option menu, goes through without taking
 * it, so the {@code 1} that follows still works. Once a page is taken every further guarded key is blocked until
 * the next page loads. That is not just tidiness: the plugin sees a key before the client handles it, so a key
 * let through just as the last page closes would land in the chat box.
 *
 * <p>Every guarded key pressed on a dialogue also <em>arms</em> the guard. After the dialogue closes, an armed
 * guard blocks further guarded keys until the player stops pressing them for the window. A pause of the same
 * length also frees a taken page, in case it ignored the key after all. A key that is still held down counts as
 * pressing, so the pause only starts at release. Any other key ends the guard immediately: that is deliberate
 * typing.
 *
 * <p>Dialogue events arrive on the client thread and key events on the AWT thread; every field is volatile or
 * concurrent and no decision needs more than one of them to be consistent, so no locking is required.
 */
final class GuardState
{
	/** What to do with a guarded key press. */
	enum Decision
	{
		/** Let it through: a dialogue is open to take it, or the guard has lapsed. */
		PASS,
		/** Block it quietly: the open page already has its key, and would mostly ignore this one anyway. */
		HOLD,
		/** Block it: spill-over from a dialogue that just closed, which would otherwise land in the chat box. */
		BLOCK
	}

	/** No key event for this long means the release was lost (focus change); a stuck "held" must not pin the guard. */
	static final long HELD_STALE_MS = 3000;

	private final LongSupplier windowMs;

	/** dialogue interface groups currently open. A set, so a page reloaded in place cannot double-count. */
	private final Set<Integer> openDialogues = ConcurrentHashMap.newKeySet();
	/** the most recently opened page */
	private volatile int page = -1;
	/** the open page has had a key it accepts */
	private volatile boolean pageTaken;
	/** guarded keys were pressed on the dialogue that is open (or was just open) */
	private volatile boolean armed;
	/** when the last guarded key was pressed or released */
	private volatile long lastGuardedAt;
	/** a guarded key is physically held down */
	private volatile boolean guardedKeyHeld;

	GuardState(LongSupplier windowMs)
	{
		this.windowMs = windowMs;
	}

	void reset()
	{
		openDialogues.clear();
		page = -1;
		pageTaken = false;
		armed = false;
		lastGuardedAt = 0;
		guardedKeyHeld = false;
	}

	boolean dialogueOpen()
	{
		return !openDialogues.isEmpty();
	}

	/** The page the next guarded key goes to, or -1 if none has opened. */
	int page()
	{
		return page;
	}

	/**
	 * A dialogue page appeared (or re-appeared): it is waiting for a key. The guard stays armed: a page can open and
	 * close again before a key reaches it, and the player mashing through it is still mashing.
	 */
	void dialogueOpened(int group)
	{
		openDialogues.add(group);
		page = group;
		pageTaken = false;
	}

	/** A dialogue page went away. Stays armed: the guarded keys that follow are the spill-over this exists to catch. */
	void dialogueClosed(int group)
	{
		openDialogues.remove(group);
	}

	/** A non-guarded, non-modifier key: the player is typing on purpose. */
	void otherKeyPressed()
	{
		armed = false;
	}

	/** A guarded key was pressed at {@code now}; {@code pageAccepts} says whether the open page acts on it. */
	Decision guardedKeyPressed(long now, boolean pageAccepts)
	{
		boolean inWindow = withinWindow(now);
		guardedKeyHeld = true;
		if (dialogueOpen())
		{
			armed = true;
			lastGuardedAt = now;
			if (pageTaken && inWindow)
			{
				return Decision.HOLD;
			}
			pageTaken = pageAccepts;
			return Decision.PASS;
		}
		if (armed && inWindow)
		{
			lastGuardedAt = now;
			return Decision.BLOCK;
		}
		armed = false;
		return Decision.PASS;
	}

	/** A guarded key was released at {@code now}: the pause starts here, not at the press. */
	void guardedKeyReleased(long now)
	{
		guardedKeyHeld = false;
		lastGuardedAt = now;
	}

	/** Mark {@code now} as guarded-key activity without changing the armed state (used by the leading-space rule). */
	void touch(long now)
	{
		lastGuardedAt = now;
	}

	private boolean withinWindow(long now)
	{
		long since = now - lastGuardedAt;
		if (guardedKeyHeld && since < HELD_STALE_MS)
		{
			return true;
		}
		return since < windowMs.getAsLong();
	}
}

package com.dialogueguard;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DialogueGuardPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DialogueGuardPlugin.class);
		RuneLite.main(args);
	}
}

package com.dialogueguard;

import static com.dialogueguard.DialogueKeys.Kind.DIGIT;
import static com.dialogueguard.DialogueKeys.Kind.ENTER;
import static com.dialogueguard.DialogueKeys.Kind.OTHER;
import static com.dialogueguard.DialogueKeys.Kind.SPACE;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.awt.event.KeyEvent;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;

public class DialogueKeysTest
{
	@Test
	public void digitsOnTheTopRowAndTheNumpadAreBothDigits()
	{
		for (int k = KeyEvent.VK_1; k <= KeyEvent.VK_9; k++)
		{
			assertEquals(DIGIT, DialogueKeys.kind(k));
		}
		for (int k = KeyEvent.VK_NUMPAD1; k <= KeyEvent.VK_NUMPAD9; k++)
		{
			assertEquals(DIGIT, DialogueKeys.kind(k));
		}
	}

	@Test
	public void zeroIsNotADialogueKey()
	{
		// no dialogue has a tenth option, so 0 is ordinary typing
		assertEquals(OTHER, DialogueKeys.kind(KeyEvent.VK_0));
		assertEquals(OTHER, DialogueKeys.kind(KeyEvent.VK_NUMPAD0));
	}

	@Test
	public void spaceEnterAndLetters()
	{
		assertEquals(SPACE, DialogueKeys.kind(KeyEvent.VK_SPACE));
		assertEquals(ENTER, DialogueKeys.kind(KeyEvent.VK_ENTER));
		assertEquals(OTHER, DialogueKeys.kind(KeyEvent.VK_A));
	}

	@Test
	public void optionMenusTakeDigitsOnly()
	{
		assertTrue(DialogueKeys.pageAccepts(InterfaceID.CHATMENU, KeyEvent.VK_1));
		assertTrue(DialogueKeys.pageAccepts(InterfaceID.CHATMENU, KeyEvent.VK_NUMPAD2));
		assertFalse(DialogueKeys.pageAccepts(InterfaceID.CHATMENU, KeyEvent.VK_SPACE));
		assertFalse(DialogueKeys.pageAccepts(InterfaceID.CHATMENU, KeyEvent.VK_ENTER));
	}

	@Test
	public void makeXTakesDigitsAndSpace()
	{
		assertTrue(DialogueKeys.pageAccepts(InterfaceID.SKILLMULTI, KeyEvent.VK_3));
		assertTrue(DialogueKeys.pageAccepts(InterfaceID.SKILLMULTI, KeyEvent.VK_SPACE));
		assertFalse(DialogueKeys.pageAccepts(InterfaceID.SKILLMULTI, KeyEvent.VK_ENTER));
