	@Test
	public void continuePagesTakeSpaceOnly()
	{
		int[] pages = {InterfaceID.CHAT_LEFT, InterfaceID.CHAT_RIGHT, InterfaceID.MESSAGEBOX, InterfaceID.OBJECTBOX,
			InterfaceID.OBJECTBOX_DOUBLE, InterfaceID.LEVELUP_DISPLAY};
		for (int page : pages)
